// D3: the Barometer gauge, one implementation. Style A of /embed/barometer renders it today; the /bitcoin-barometer
// page reuses gaugeMarkup() + needleGeometry() (AMENDMENT 2). SVG, CSS and owl are copied byte for byte from
// design/project-nakamoto-notes/d3-widget-mock-v3.html, a 1:1 port of the app's components/BitcoinBarometer.tsx.

export const OWL_DATA_URI = 'data:image/png;base64,';

// App needle formula (BitcoinBarometer.tsx): arc centre (180,150), needle base (180,120), h = feed.heatScore (0..1).
// The same function source is embedded in the page script (needleGeometry.toString()), so there is one formula.
export function needleGeometry(h) {
  var a = Math.PI + h * Math.PI, tx = 180 + 120 * Math.cos(a), ty = 150 + 120 * Math.sin(a);
  var ang = Math.atan2(tx - 180, -(ty - 120)) * 180 / Math.PI, n = 4 * (h - 0.5) * (h - 0.5), L = 60 + 25 * n;
  return '<path transform="rotate(' + ang + ' 180 120)" d="M 180 ' + (120 - L) + ' L 184 ' + (120 - 8) + ' L 180 120 L 176 ' + (120 - 8) + ' Z" fill="url(#ndl)" filter="url(#ns)" stroke="#B8860B" stroke-width=".5"/>';
}

