export function gaugeMarkup(score = '', needle = '') {
  return `<div class="gw">${gaugeSvg(score, needle)}</div>`;
}

// Style-A card, the one renderer for /embed/barometer (v empty, footer with ids) and the /bitcoin-barometer page
// (v filled server-side). v: { zone, zoneStyle, date, status, score, needle }.
export function cardAHtml(v, footer, disclaimer) {
  const { score = '', needle = '', zone = '', zoneStyle = '', date = '', status = '' } = v || {};
  return `<div class="card"><div class="brand">NAKAMOTO NOTES</div>
<img class="owl" src="${OWL_DATA_URI}" alt="">
<div class="t">BITCOIN<br>BAROMETER</div>
${gaugeMarkup(score, needle)}
<div class="zone" data-nn-field="zone"${zoneStyle}>${zone}</div><div class="date"><span data-nn-field="date">${date}</span> · 0-100 market heat from 10 indicators</div>
<div class="status" data-nn-field="status">${status}</div>
${footer}
<div class="disc">${disclaimer}</div></div>`;
}
